 <?php $__env->startSection('content'); ?><div class="d-flex flex-wrap justify-content-between align-items-center mb-3"><div><h2>Jadwal Pelajaran</h2><p class="text-muted mb-0">Hasil penjadwalan dan optimasi multi-kriteria</p></div><?php if(auth()->user()->role==='admin'): ?><form method="POST" action="<?php echo e(route('schedules.generate')); ?>"><?php echo csrf_field(); ?><button class="btn btn-primary">Generate Jadwal</button></form><?php endif; ?></div><div class="card p-3 table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Hari/Jam</th><th>Kelas</th><th>Mata Pelajaran</th><th>Guru</th><th>Ruangan</th><th>Skor</th><th>Status</th><?php if(auth()->user()->role==='admin'): ?><th>Aksi</th><?php endif; ?></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $schedules; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($s->period->day); ?><br><small><?php echo e(substr($s->period->start_time,0,5)); ?>–<?php echo e(substr($s->period->end_time,0,5)); ?> (<?php echo e($s->period->period_number); ?>)</small></td><td><?php echo e($s->assignment->schoolClass->name); ?></td><td><?php echo e($s->assignment->subject->name); ?> <small class="text-muted">(sesi <?php echo e($s->session_number); ?>)</small></td><td><?php echo e($s->assignment->teacher->name); ?></td><td><?php echo e($s->room->name); ?></td><td><?php echo e(number_format($s->optimization_score,1)); ?></td><td><?php if($s->locked): ?><span class="badge text-bg-warning">Terkunci</span><?php else: ?><span class="badge text-bg-success">Aktif</span><?php endif; ?></td><?php if(auth()->user()->role==='admin'): ?><td class="d-flex gap-1"><form method="POST" action="<?php echo e(route('schedules.lock',$s)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><button class="btn btn-sm btn-outline-secondary"><?php echo e($s->locked?'Buka kunci':'Kunci'); ?></button></form><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#r<?php echo e($s->id); ?>">Reschedule</button><div class="modal fade" id="r<?php echo e($s->id); ?>" tabindex="-1"><div class="modal-dialog"><form method="POST" action="<?php echo e(route('schedules.reschedule',$s)); ?>" class="modal-content"><?php echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title">Reschedule jadwal</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p><?php echo e($s->assignment->subject->name); ?> — <?php echo e($s->assignment->schoolClass->name); ?></p><label class="form-label">Alasan perubahan</label><textarea name="reason" class="form-control" required placeholder="Contoh: guru berhalangan hadir"></textarea></div><div class="modal-footer"><button class="btn btn-primary">Cari slot pengganti</button></div></form></div></div></td><?php endif; ?></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="8" class="text-center text-muted py-4">Belum ada jadwal. Admin dapat menekan Generate Jadwal.</td></tr><?php endif; ?></tbody></table></div><?php $__env->stopSection(); ?>
